import heapq
from collections import Counter

class Solution:
    def isPossibleDivide(self, nums: List[int], k: int) -> bool:
        if len(nums) % k:
            return False
        cnt = Counter(nums)
        heap = list(cnt.keys())
        heapq.heapify(heap)
        while heap:
            x = heap[0]
            for v in range(x, x + k):
                if cnt[v] == 0:
                    return False
                cnt[v] -= 1
            while heap and cnt[heap[0]] == 0:
                heapq.heappop(heap)
        return True

