class Solution {
public:
    bool isPossibleDivide(vector<int>& nums, int k) {
        if (nums.size() % k) return false;
        map<int,int> cnt;
        for (int x : nums) cnt[x]++;
        while (!cnt.empty()) {
            int x = cnt.begin()->first;
            for (int v = x; v < x + k; v++) {
                auto it = cnt.find(v);
                if (it == cnt.end()) return false;
                if (--it->second == 0) cnt.erase(it);
            }
        }
        return true;
    }
};

