import java.util.*;

class Solution {
    public boolean isPossibleDivide(int[] nums, int k) {
        if (nums.length % k != 0) return false;
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : nums) cnt.merge(x, 1, Integer::sum);
        PriorityQueue<Integer> heap = new PriorityQueue<>(cnt.keySet());
        while (!heap.isEmpty()) {
            int x = heap.peek();
            for (int v = x; v < x + k; v++) {
                int c = cnt.getOrDefault(v, 0);
                if (c == 0) return false;
                cnt.put(v, c - 1);
            }
            while (!heap.isEmpty() && cnt.get(heap.peek()) == 0) heap.poll();
        }
        return true;
    }
}

