var isPossibleDivide = function(nums, k) {
    if (nums.length % k !== 0) return false;
    const cnt = new Map();
    for (const x of nums) cnt.set(x, (cnt.get(x) || 0) + 1);
    const heap = [...cnt.keys()];
    heap.sort((a, b) => a - b);
    let size = heap.length;
    const pop = () => { size--; return heap.shift(); };
    while (size > 0) {
        const x = heap[0];
        for (let v = x; v < x + k; v++) {
            const c = cnt.get(v) || 0;
            if (c === 0) return false;
            cnt.set(v, c - 1);
        }
        while (size > 0 && cnt.get(heap[0]) === 0) pop();
    }
    return true;
};

